import{_ as e,a,c as r,ac as l}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"羽毛球规则 · 从挑边到结束：新手比赛顺序至官方来源与查阅方法","description":"以 BWF 21 分制规则讲解单打和双打的场地边线、发球站位、轮转、违例、重发与常见判例。","frontmatter":{"title":"羽毛球规则 · 从挑边到结束：新手比赛顺序至官方来源与查阅方法","description":"以 BWF 21 分制规则讲解单打和双打的场地边线、发球站位、轮转、违例、重发与常见判例。","splitFrom":"life/personal/sports/badminton-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"羽毛球规则","summary":"以 BWF 21 分制规则讲解单打和双打的场地边线、发球站位、轮转、违例、重发与常见判例。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"羽毛球规则 · 适用范围与规则版本至违例、擦网与重发","link":"/life/personal/sports/badminton-rules-part-01"},"next":{"text":"排球规则","link":"/life/personal/sports/volleyball-rules"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"羽毛球规则 · 适用范围与规则版本至违例、擦网与重发","link":"/life/personal/sports/badminton-rules-part-01"},"next":{"text":"排球规则","link":"/life/personal/sports/volleyball-rules"}},"headers":[],"relativePath":"life/personal/sports/badminton-rules-part-02.md","filePath":"life/personal/sports/badminton-rules-part-02.md"}'),n={name:"life/personal/sports/badminton-rules-part-02.md"};function o(i,t,d,s,p,h){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="羽毛球规则-·-从挑边到结束-新手比赛顺序至官方来源与查阅方法" tabindex="-1">羽毛球规则 · 从挑边到结束：新手比赛顺序至官方来源与查阅方法 <a class="header-anchor" href="#羽毛球规则-·-从挑边到结束-新手比赛顺序至官方来源与查阅方法" aria-label="Permalink to &quot;羽毛球规则 · 从挑边到结束：新手比赛顺序至官方来源与查阅方法&quot;">​</a></h1><p><a href="/life/personal/sports/badminton-rules">返回分篇目录</a></p><p>羽毛球每个回合都争夺一分。理解规则的关键是把“发球时的有效区域”和“相持时的有效区域”分开，再用发球方的得分判断左右发球区。</p><h2 id="从挑边到结束-新手比赛顺序" tabindex="-1">从挑边到结束：新手比赛顺序 <a class="header-anchor" href="#从挑边到结束-新手比赛顺序" aria-label="Permalink to &quot;从挑边到结束：新手比赛顺序 {#从挑边到结束-新手比赛顺序}&quot;">​</a></h2><p>挑边后先确定首发者、接发者与场地；双打记下四个人的初始左右关系。每分结束，先确认哪队得分，再用<strong>下一次发球队的新得分</strong>判断奇左偶右，最后确认具体发、接球员。不要只跟着上一个球的站位发球。</p><p>一方先到 11 分按规则间歇，然后继续这一局；达到本版的赢局条件后记下局分，胜方下一局先发。打到决胜局时，领先方到 11 分还要换边，已有比分保留。这个顺序把报分、发球权和换边分开，比较容易查出记错的是哪一步。</p><h3 id="三个比分与判罚例子" tabindex="-1">三个比分与判罚例子 <a class="header-anchor" href="#三个比分与判罚例子" aria-label="Permalink to &quot;三个比分与判罚例子 {#三个比分与判罚例子}&quot;">​</a></h3><ol><li><strong>单打甲 20∶乙 20，甲在右区发球。</strong> 甲赢后为 21∶20，比赛继续，甲改从左区发；乙再赢为 21∶21，乙获得发球权，从左区发。领先到 22∶20 才能在这个阶段结束本局。</li><li><strong>双打 14∶14，本方发球。</strong> 发球落在图中①，超过双打后发球线，直接失分，变为 14∶15，对方取得发球权；若这是相持中的一次回球落点，不能因其超过后发球线判出界。</li><li><strong>甲 29∶乙 29，乙发球。</strong> 发球擦网后落入甲方正确发球区，甲认为要重发而没有接，乙以 30∶29 赢局。羽毛球这种擦网发球有效，而且本版有 30 分上限。</li></ol><h3 id="球路与配合术语" tabindex="-1">球路与配合术语 <a class="header-anchor" href="#球路与配合术语" aria-label="Permalink to &quot;球路与配合术语 {#球路与配合术语}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>入门理解</th></tr></thead><tbody><tr><td>高远球</td><td>把球送向后场，常用于让对方离开网前；不等于球高就能忽略后界</td></tr><tr><td>吊球、网前球</td><td>将球送到对方前场的不同处理方式，短发球线不是相持禁落区</td></tr><tr><td>杀球</td><td>向下进攻的球路，能否得分仍取决于合法击球和落点</td></tr><tr><td>平抽挡</td><td>较低、较快的往返球路，双打中常见</td></tr><tr><td>前后站位、左右站位</td><td>双打的配合选择，不是必须每球照做的轮转规则</td></tr><tr><td>交换发球权</td><td>接发方赢回合后得分并发球；没有另一次“第二发球权”</td></tr></tbody></table><p>观察双打时，可以先看“谁接发、同伴让出哪条球路”，再看回合中两人如何补位。两人交换前后位置不会自动改变下一球的法定发接球次序。</p><h2 id="常见判例与自测" tabindex="-1">常见判例与自测 <a class="header-anchor" href="#常见判例与自测" aria-label="Permalink to &quot;常见判例与自测 {#常见判例与自测}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>判断与理由</th></tr></thead><tbody><tr><td>单打发球落在底线与双打后发球线之间</td><td>未越出单打发球区，其他条件满足即有效</td></tr><tr><td>双打发球落在同一片区域</td><td>发球过长，违例；双打相持打到此处则可以</td></tr><tr><td>球托落在线上</td><td>界内</td></tr><tr><td>20∶20 后一方得到第 21 分</td><td>继续打，尚未领先 2 分</td></tr><tr><td>29∶29 后一方得到第 30 分</td><td>该方赢局，达到封顶分</td></tr><tr><td>双打接发同伴抢在指定接发球员前回球</td><td>接发方违例</td></tr></tbody></table><p>自己再回答四题：</p><ol><li>发球击球点在 1.15 米以下，但两脚都离地，合法吗？</li><li>单打自己 8 分、对手 7 分，自己从哪边发球？</li><li>双打接发方赢球后，两名球员是否立刻交换左右发球区？</li><li>发球擦网后正确落区，接发球员没有接，因为以为需要重发，谁得分？</li></ol><p><strong>答案：</strong> ①不合法，还须符合双脚接地和静止要求。②右区，按发球员自己的偶数分判断。③不交换，按新得分决定由原来相应区域的队员发球。④发球方得分；这种擦网发球有效。</p><h2 id="官方来源与查阅方法" tabindex="-1">官方来源与查阅方法 <a class="header-anchor" href="#官方来源与查阅方法" aria-label="Permalink to &quot;官方来源与查阅方法 {#官方来源与查阅方法}&quot;">​</a></h2><ul><li><a href="https://corporate.bwfbadminton.com/statutes/" target="_blank" rel="noopener noreferrer">BWF Statutes 官方规则入口</a>：Section 4.1《Laws of Badminton》；第 1 条查场地，第 7—8 条查计分与换边，第 9—12 条查发球和单双打，第 13—16 条查违例、重发和间歇。</li><li><a href="https://corporate.bwfbadminton.com/" target="_blank" rel="noopener noreferrer">BWF Corporate 官方公告</a>：计分制度更新应同时核对决议内容、适用赛事和正式生效时间，再选择对应的规则版本。</li><li><a href="https://system.bwfbadminton.com/documents/folder_1_81/Statutes/CHAPTER-4---RULES-OF-THE-GAME/SECTION%204.1-%20Laws%20of%20Badminton.pdf" target="_blank" rel="noopener noreferrer">BWF Section 4.1 官方 PDF</a>：官方可更新的文件地址；下载后仍需确认封面版本和生效日期，不能只凭链接名称认定为 2025 版。</li></ul><p>本文是 21 分制的中文学习整理，尚未完成对所列版本官方原文的逐条校核。参赛前应确认赛事适用的规则版本，以及是否另有局数、计分或场地特别规定。</p>',19)])])}const b=e(n,[["render",o]]);export{u as __pageData,b as default};
